SELECT DISTINCT p.id FROM product p INNER JOIN coupon_category cc ON cc.coupon_id = #{couponId} INNER JOIN category parent ON cc.category_id = parent.id LEFT JOIN category child ON child.parent_id = cc.category_id AND parent.parent_id = 0 WHERE p.id IN
#{productId}
AND ( p.category_id = cc.category_id OR p.category_id = child.id )
